  "qa": [
    {
      "question": "学校是否考虑为家庭条件允许的学生提供上门教学服务？",
      "answer": "学校计划针对家庭条件允许的学生提供上门教学服务，以替代部分课堂学习，具体通过适当定价实现一对一教学。"
    },
    {
      "question": "学校如何通过赠品活动促进课程销售？",
      "answer": "学校拟通过赠送英语读本、动画片光盘、钢笔等学习用品作为课程促销手段，同时支持跨课程赠品组合以吸引学生。"
    },
    {
      "question": "学校将如何有效分发宣传材料以避免资源浪费？",
      "answer": "学校计划在课间或课程结束时由教师向学生简要介绍并发放宣传材料，以PPT形式发送至家长群，确保环保且避免传单散失。"
    }
  ]
}
